    cands = []
    try:
        cands.append(b"\x01" + lzma.compress(data, format=lzma.FORMAT_RAW, filters=_FILTERS))
    except Exception:
        pass
    cands.append(b"\x02" + zlib.compress(data, 9))
    cands.append(b"\x03" + bz2.compress(data, 9))
