    return [{"id": lzma.FILTER_LZMA2, "preset": 9 | lzma.PRESET_EXTREME, "lc": lc, "lp": lp, "pb": pb,
             "nice_len": 273, "mf": lzma.MF_BT4, "depth": 0}]

_CFGS = [(0, 0, 0), (2, 0, 0), (4, 0, 0), (3, 0, 0)]

def _xform(data):
    if not data or max(data) >= 0x80:
        return None
    cnt = Counter(_TOK.findall(data))
    cand = sorted(cnt.items(), key=lambda kv: -(kv[1] * (len(kv[0]) - 2)))
    words = [w for w, c in cand if c * (len(w) - 2) > len(w) + 1][:32768]
    if not words:
        return None
    idx = {w: i for i, w in enumerate(words)}
    def rep(m):
        i = idx.get(m.group(0))
        if i is None:
            return m.group(0)
        return bytes((0x80 | (i >> 8), i & 0xFF))
    body = _TOK.sub(rep, data)
    dic = b"\n".join(words)
    return len(dic).to_bytes(4, "big") + dic + body

