        return None
    idx = {w: i for i, w in enumerate(words)}
    def rep(m):
        i = idx.get(m.group(0))
        if i is None:
            return m.group(0)
        if i < 64:
            return bytes((0x80 + i,))
        i -= 64
        return bytes((0xC0 | (i >> 8), i & 0xFF))
    body = _TOK.sub(rep, data)
    dic = b"\n".join(words)
